755 | /// `Message = UserMessage | AssistantMessage | ToolResultMessage`. The base
756 | /// provider-facing message type.
757 | #[derive(Debug, Clone, PartialEq, Serialize)]
758 | #[serde(tag = "role", rename_all = "camelCase")]
759 | pub enum Message {
760 |     User(UserMessage),
761 |     Assistant(Box<AssistantMessage>),
762 |     ToolResult(Box<ToolResultMessage>),
763 | }
764 | 
765 | // The concrete message structs intentionally retain their `role` field so
766 | // they serialize exactly like Pi's TypeScript messages. An internally tagged
767 | // enum would consume that field before deserializing the struct variant,
768 | // causing `missing field role` for otherwise valid messages. Decode the tag
769 | // explicitly and pass the complete object through to the concrete type.
770 | impl<'de> Deserialize<'de> for Message {
771 |     fn deserialize<D: serde::Deserializer<'de>>(deserializer: D) -> Result<Self, D::Error> {
772 |         let value = serde_json::Value::deserialize(deserializer)?;
773 |         let role = value
774 |             .get("role")
775 |             .and_then(serde_json::Value::as_str)
776 |             .ok_or_else(|| serde::de::Error::missing_field("role"))?;
777 |         match role {
778 |             "user" => serde_json::from_value(value)
779 |                 .map(Message::User)
780 |                 .map_err(serde::de::Error::custom),
781 |             "assistant" => serde_json::from_value(value)
782 |                 .map(|message| Message::Assistant(Box::new(message)))
783 |                 .map_err(serde::de::Error::custom),
784 |             "toolResult" => serde_json::from_value(value)
785 |                 .map(|message| Message::ToolResult(Box::new(message)))
786 |                 .map_err(serde::de::Error::custom),
787 |             other => Err(serde::de::Error::unknown_variant(
788 |                 other,
789 |                 &["user", "assistant", "toolResult"],
790 |             )),
791 |         }
792 |     }
793 | }
794 | 
795 | impl From<UserMessage> for Message {
796 |     fn from(m: UserMessage) -> Self {
797 |         Message::User(m)
798 |     }
799 | }
800 | impl From<AssistantMessage> for Message {
801 |     fn from(m: AssistantMessage) -> Self {
802 |         Message::Assistant(Box::new(m))
803 |     }
804 | }
805 | impl From<ToolResultMessage> for Message {
806 |     fn from(m: ToolResultMessage) -> Self {
807 |         Message::ToolResult(Box::new(m))
808 |     }
809 | }
